"""Cash flows generated by instruments."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True, slots=True)
class FixedCoupon:
    """A fixed-rate coupon.

    Attributes:
        payment_date: Date the coupon is paid (equal to ``accrual_end``: no payment lag).
        amount: Coupon amount in currency, ``nominal * rate * accrual``.
        accrual_start: Start of the accrual period.
        accrual_end: End of the accrual period.
        ref_start: Start of the regular reference period (ACT/ACT ICMA).
        ref_end: End of the regular reference period (ACT/ACT ICMA).
        accrual: Accrual year fraction under the coupon day count.
    """

    payment_date: date
    amount: float
    accrual_start: date
    accrual_end: date
    ref_start: date
    ref_end: date
    accrual: float


@dataclass(frozen=True, slots=True)
class Redemption:
    """Repayment of principal.

    Attributes:
        payment_date: Date the principal is repaid.
        amount: Principal amount in currency.
    """

    payment_date: date
    amount: float


type Cashflow = FixedCoupon | Redemption
